@Component
export struct SyncMenu {
  private actions = [
    {
      caption: 'Restart sync',
      run: () => {
        this.worker.stopSync()
      }
    },
    {
      caption: 'Stop sync',
      run: () => {
        this.worker.stopSync()
      }
    }
  ]
  build() {
    Column() {
      ForEach(this.actions, (action: Action) => {
        Button(action.caption).onClick(action.run)
      })
    }
  }
}

